// Turns spec/*.json into Swift and Kotlin source so the native ports contain logic only.
// Run: pnpm gen:native   (a test fails if the generated files are out of date)
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";

const root = new URL("../", import.meta.url);
const spec = (p: string) => JSON.parse(readFileSync(new URL(`spec/${p}`, root), "utf8"));

const letters = spec("letters.json") as Record<string, number[]>;
const parts = spec("parts/parts.json").parts as Array<{ id: string; slot: string; tone: string; dx: number[]; rows: string[] }>;
const pal = spec("palettes.json") as {
  white: string;
  groups: Record<"pastel" | "vivid" | "deep", Array<Record<string, string>>>;
  presets: Record<string, string[] | string>;
};
const faces = spec("faces/faces.json") as {
  eyes: Record<string, Record<string, string[]>>;
  mouths: Record<string, string[]>;
  props: Record<string, { x: number; y: number; rows: string[] } | null>;
};

const motion = spec("motion.json") as {
  styles: Record<string, { lift: number[]; dx: number[]; lean: number[]; squash: number[]; wave: string; amp: number }>;
  breathe: { squash: number[] };
  jump: { lift: number[]; squash: number[] };
};
const MOTION_ORDER = ["bounce", "sway", "waddle", "slither", "float", "pulse"];

const LETTERS = "abcdefghijklmnopqrstuvwxyz".split("");
const presetNames = Object.keys(pal.presets).filter((k) => Array.isArray(pal.presets[k]));
const q = (s: string): string => JSON.stringify(s);
const list = (xs: Array<string | number>, f: (x: string | number) => string = String): string => xs.map(f).join(", ");
const qlist = (xs: string[]): string => list(xs, (x) => q(String(x)));

export function swift(): string {
  const entry = (e: Record<string, string>): string =>
    `PaletteEntry(name: ${q(e.name!)}, body: ${q(e.body!)}, shade: ${q(e.shade!)}, light: ${q(e.light!)}, outline: ${q(e.outline!)}, accent: ${q(e.accent!)})`;
  const moodMap = (m: Record<string, string[]>): string =>
    Object.entries(m).map(([k, v]) => `    ${q(k)}: [${qlist(v)}]`).join(",\n");
  return `// Generated by scripts/gen-native.ts from spec/. Do not edit by hand.

struct PartDef {
    let id: String
    let slot: String
    let tone: String
    let dx: [Int]
    let rows: [String]
}

struct PaletteEntry {
    let name: String
    let body: String
    let shade: String
    let light: String
    let outline: String
    let accent: String
}

struct PropDef {
    let x: Int
    let y: Int
    let rows: [String]
}

struct MotionStyle {
    let lift: [Int]
    let dx: [Int]
    let lean: [Int]
    let squash: [Int]
    let wave: String
    let amp: Int
}

enum SpecData {
    /// For letters a...z: [round, sharp, heavy, light, rare].
    static let letters: [[Int]] = [
${LETTERS.map((l) => `        [${list(letters[l]!)}]`).join(",\n")}
    ]

    static let parts: [PartDef] = [
${parts.map((p) => `        PartDef(id: ${q(p.id)}, slot: ${q(p.slot)}, tone: ${q(p.tone)}, dx: [${list(p.dx)}], rows: [${qlist(p.rows)}])`).join(",\n")}
    ]

    static let white = ${q(pal.white)}
    static let pastel: [PaletteEntry] = [
${pal.groups.pastel.map((e) => `        ${entry(e)}`).join(",\n")}
    ]
    static let vivid: [PaletteEntry] = [
${pal.groups.vivid.map((e) => `        ${entry(e)}`).join(",\n")}
    ]
    static let deep: [PaletteEntry] = [
${pal.groups.deep.map((e) => `        ${entry(e)}`).join(",\n")}
    ]
    /// Four colors, darkest to lightest.
    static let presets: [String: [String]] = [
${presetNames.map((n) => `        ${q(n)}: [${qlist(pal.presets[n] as string[])}]`).join(",\n")}
    ]

    /// eyes[style][mood] is a 3x3 pattern for the left eye.
    static let eyes: [String: [String: [String]]] = [
${Object.entries(faces.eyes).map(([s, m]) => `        ${q(s)}: [\n${moodMap(m).replace(/^/gm, "    ")}\n        ]`).join(",\n")}
    ]
    static let mouths: [String: [String]] = [
${moodMap(faces.mouths).replace(/^/gm, "    ")}
    ]
    static let props: [String: PropDef] = [
${Object.entries(faces.props).filter(([, v]) => v).map(([k, v]) => `        ${q(k)}: PropDef(x: ${v!.x}, y: ${v!.y}, rows: [${qlist(v!.rows)}])`).join(",\n")}
    ]

    /// Idle motion loops (8 steps each), one per style.
    static let motionStyles: [String: MotionStyle] = [
${MOTION_ORDER.map((n) => { const m = motion.styles[n]!; return `        ${q(n)}: MotionStyle(lift: [${list(m.lift)}], dx: [${list(m.dx)}], lean: [${list(m.lean)}], squash: [${list(m.squash)}], wave: ${q(m.wave)}, amp: ${m.amp})`; }).join(",\n")}
    ]
    static let breatheSquash: [Int] = [${list(motion.breathe.squash)}]
    static let jumpLift: [Int] = [${list(motion.jump.lift)}]
    static let jumpSquash: [Int] = [${list(motion.jump.squash)}]
}
`;
}

export function kotlin(): string {
  const entry = (e: Record<string, string>): string =>
    `PaletteEntry(${q(e.name!)}, ${q(e.body!)}, ${q(e.shade!)}, ${q(e.light!)}, ${q(e.outline!)}, ${q(e.accent!)})`;
  const moodMap = (m: Record<string, string[]>): string =>
    Object.entries(m).map(([k, v]) => `        ${q(k)} to listOf(${qlist(v)})`).join(",\n");
  return `// Generated by scripts/gen-native.ts from spec/. Do not edit by hand.
package dev.pixie

internal class PartDef(val id: String, val slot: String, val tone: String, val dx: List<Int>, val rows: List<String>)

internal class PaletteEntry(
    val name: String, val body: String, val shade: String, val light: String, val outline: String, val accent: String,
)

internal class PropDef(val x: Int, val y: Int, val rows: List<String>)

internal class MotionStyle(
    val lift: List<Int>, val dx: List<Int>, val lean: List<Int>, val squash: List<Int>, val wave: String, val amp: Int,
)

internal object SpecData {
    /** For letters a..z: [round, sharp, heavy, light, rare]. */
    val letters: List<List<Int>> = listOf(
${LETTERS.map((l) => `        listOf(${list(letters[l]!)})`).join(",\n")}
    )

    val parts: List<PartDef> = listOf(
${parts.map((p) => `        PartDef(${q(p.id)}, ${q(p.slot)}, ${q(p.tone)}, listOf(${list(p.dx)}), listOf(${qlist(p.rows)}))`).join(",\n")}
    )

    const val white = ${q(pal.white)}
    val pastel: List<PaletteEntry> = listOf(
${pal.groups.pastel.map((e) => `        ${entry(e)}`).join(",\n")}
    )
    val vivid: List<PaletteEntry> = listOf(
${pal.groups.vivid.map((e) => `        ${entry(e)}`).join(",\n")}
    )
    val deep: List<PaletteEntry> = listOf(
${pal.groups.deep.map((e) => `        ${entry(e)}`).join(",\n")}
    )
    /** Four colors, darkest to lightest. */
    val presets: Map<String, List<String>> = mapOf(
${presetNames.map((n) => `        ${q(n)} to listOf(${qlist(pal.presets[n] as string[])})`).join(",\n")}
    )

    /** eyes[style][mood] is a 3x3 pattern for the left eye. */
    val eyes: Map<String, Map<String, List<String>>> = mapOf(
${Object.entries(faces.eyes).map(([s, m]) => `        ${q(s)} to mapOf(\n${moodMap(m).replace(/^/gm, "    ")}\n        )`).join(",\n")}
    )
    val mouths: Map<String, List<String>> = mapOf(
${moodMap(faces.mouths)}
    )
    val props: Map<String, PropDef> = mapOf(
${Object.entries(faces.props).filter(([, v]) => v).map(([k, v]) => `        ${q(k)} to PropDef(${v!.x}, ${v!.y}, listOf(${qlist(v!.rows)}))`).join(",\n")}
    )

    /** Idle motion loops (8 steps each), one per style. */
    val motionStyles: Map<String, MotionStyle> = mapOf(
${MOTION_ORDER.map((n) => { const m = motion.styles[n]!; return `        ${q(n)} to MotionStyle(listOf(${list(m.lift)}), listOf(${list(m.dx)}), listOf(${list(m.lean)}), listOf(${list(m.squash)}), ${q(m.wave)}, ${m.amp})`; }).join(",\n")}
    )
    val breatheSquash: List<Int> = listOf(${list(motion.breathe.squash)})
    val jumpLift: List<Int> = listOf(${list(motion.jump.lift)})
    val jumpSquash: List<Int> = listOf(${list(motion.jump.squash)})
}
`;
}

export const OUTPUTS: Array<[string, () => string]> = [
  ["packages/swift/Sources/Pixie/Generated/SpecData.swift", swift],
  ["packages/kotlin/pixie/src/main/kotlin/dev/pixie/SpecData.kt", kotlin],
];

if (process.argv[1]?.endsWith("gen-native.ts")) {
  for (const [path, gen] of OUTPUTS) {
    const url = new URL(path, root);
    mkdirSync(dirname(url.pathname), { recursive: true });
    writeFileSync(url, gen());
    console.log("wrote", path);
  }
}
